//! Reading and writing the binary DNS wire format.

use std::fmt;

/// Something went wrong while turning a stream of bytes into a DNS packet.
#[derive(PartialEq, Debug)]
pub enum WireError {
    /// The packet ran out before we had finished reading a field.
    IO,

    /// A record’s stated length disagrees with the length its type demands.
    WrongRecordLength {
        stated_length: u16,
        mandated_length: MandatedLength,
    },

    /// The labels inside a record did not add up to the stated record length.
    WrongLabelLength {
        stated_length: u16,
        length_after_labels: u16,
    },

    /// A record uses a version of its format that we do not understand.
    WrongVersion {
        stated_version: u8,
        maximum_supported_version: u8,
    },

    /// Following compression pointers went on for too long.
    TooMuchRecursion(Vec<u16>),

    /// A compression pointer pointed outside of the packet.
    OutOfBounds(u16),
}

/// How long a record’s data is permitted to be.
#[derive(PartialEq, Debug, Copy, Clone)]
pub enum MandatedLength {
    /// The length has to be exactly this many bytes.
    Exactly(u16),

    /// The length has to be this many bytes or more.
    AtLeast(u16),
}

impl fmt::Display for WireError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::IO => {
                write!(f, "Malformed packet: insufficient data")
            }
            Self::WrongRecordLength { stated_length, mandated_length: MandatedLength::Exactly(len) } => {
                write!(f, "Malformed packet: record length should be {}, got {}", len, stated_length)
            }
            Self::WrongRecordLength { stated_length, mandated_length: MandatedLength::AtLeast(len) } => {
                write!(f, "Malformed packet: record length should be at least {}, got {}", len, stated_length)
            }
            Self::WrongLabelLength { stated_length, length_after_labels } => {
                write!(f, "Malformed packet: length {} was specified, but read {} bytes", stated_length, length_after_labels)
            }
            Self::WrongVersion { stated_version, maximum_supported_version } => {
                write!(f, "Malformed packet: record specifies version {}, expected up to {}", stated_version, maximum_supported_version)
            }
            Self::TooMuchRecursion(_) => {
                write!(f, "Malformed packet: too much recursion")
            }
            Self::OutOfBounds(index) => {
                write!(f, "Malformed packet: out of bounds ({})", index)
            }
        }
    }
}

/// A read-only cursor over a byte slice, tracking a position.
pub struct Reader<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> Reader<'a> {
    pub fn new(bytes: &'a [u8]) -> Self {
        Reader { bytes, pos: 0 }
    }

    pub fn position(&self) -> usize {
        self.pos
    }

    pub fn set_position(&mut self, pos: usize) {
        self.pos = pos;
    }

    pub fn len(&self) -> usize {
        self.bytes.len()
    }

    pub fn whole(&self) -> &'a [u8] {
        self.bytes
    }

    pub fn read_u8(&mut self) -> Result<u8, WireError> {
        if self.pos >= self.bytes.len() {
            return Err(WireError::IO);
        }
        let b = self.bytes[self.pos];
        self.pos += 1;
        Ok(b)
    }

    pub fn read_i8(&mut self) -> Result<i8, WireError> {
        Ok(self.read_u8()? as i8)
    }

    pub fn read_u16(&mut self) -> Result<u16, WireError> {
        let a = u16::from(self.read_u8()?);
        let b = u16::from(self.read_u8()?);
        Ok((a << 8) | b)
    }

    pub fn read_i32(&mut self) -> Result<i32, WireError> {
        Ok(self.read_u32()? as i32)
    }

    pub fn read_u32(&mut self) -> Result<u32, WireError> {
        let a = u32::from(self.read_u16()?);
        let b = u32::from(self.read_u16()?);
        Ok((a << 16) | b)
    }

    pub fn read_bytes(&mut self, count: usize) -> Result<Vec<u8>, WireError> {
        if self.bytes.len() < self.pos + count {
            return Err(WireError::IO);
        }
        let slice = self.bytes[self.pos..self.pos + count].to_vec();
        self.pos += count;
        Ok(slice)
    }

    /// Reads a DNS name, following compression pointers.
    pub fn read_labels(&mut self) -> Result<(String, u16), WireError> {
        let mut name = String::new();
        let mut bytes_read = 0_u16;
        let mut followed = false;
        let mut pointers_followed: Vec<u16> = Vec::new();
        let mut pos = self.pos;

        loop {
            if pos >= self.bytes.len() {
                return Err(WireError::IO);
            }
            let len = self.bytes[pos];
            pos += 1;
            if !followed {
                bytes_read += 1;
            }

            if len == 0 {
                break;
            } else if len & 0b1100_0000 == 0b1100_0000 {
                if pos >= self.bytes.len() {
                    return Err(WireError::IO);
                }
                let second = self.bytes[pos];
                pos += 1;
                if !followed {
                    bytes_read += 1;
                }
                let offset = (u16::from(len & 0b0011_1111) << 8) | u16::from(second);
                if pointers_followed.len() >= 8 {
                    return Err(WireError::TooMuchRecursion(pointers_followed));
                }
                if usize::from(offset) >= self.bytes.len() {
                    return Err(WireError::OutOfBounds(offset));
                }
                pointers_followed.push(offset);
                followed = true;
                pos = usize::from(offset);
            } else {
                let count = usize::from(len & 0b0011_1111);
                if self.bytes.len() < pos + count {
                    return Err(WireError::IO);
                }
                for b in &self.bytes[pos..pos + count] {
                    name.push(char::from(*b));
                }
                name.push('.');
                pos += count;
                if !followed {
                    bytes_read += u16::from(len);
                }
            }
        }

        if !followed {
            self.pos = pos;
        } else {
            self.pos += usize::from(bytes_read);
        }

        Ok((name, bytes_read))
    }
}

/// Builds up a DNS packet, byte by byte.
#[derive(Default)]
pub struct Writer {
    pub bytes: Vec<u8>,
}

impl Writer {
    pub fn new() -> Self {
        Writer { bytes: Vec::new() }
    }

    pub fn u8(&mut self, value: u8) {
        self.bytes.push(value);
    }

    pub fn u16(&mut self, value: u16) {
        self.bytes.push((value >> 8) as u8);
        self.bytes.push((value & 0xff) as u8);
    }

    pub fn u32(&mut self, value: u32) {
        self.u16((value >> 16) as u16);
        self.u16((value & 0xffff) as u16);
    }

    pub fn raw(&mut self, value: &[u8]) {
        self.bytes.extend_from_slice(value);
    }

    /// Writes a domain name in label format.
    pub fn name(&mut self, name: &str) {
        for label in name.split('.') {
            if label.is_empty() {
                continue;
            }
            self.bytes.push(label.len() as u8);
            self.bytes.extend_from_slice(label.as_bytes());
        }
        self.bytes.push(0);
    }
}

