//! The DNS record types that dog knows how to interpret.

use crate::dns::wire::*;

/// A record read out of a DNS packet.
#[derive(PartialEq, Debug)]
pub enum Record {
    A(A),
    AAAA(AAAA),
    CAA(CAA),
    CNAME(CNAME),
    EUI48(EUI48),
    EUI64(EUI64),
    HINFO(HINFO),
    LOC(LOC),
    MX(MX),
    NAPTR(NAPTR),
    NS(NS),
    OPENPGPKEY(OPENPGPKEY),
    PTR(PTR),
    SSHFP(SSHFP),
    SOA(SOA),
    SRV(SRV),
    TLSA(TLSA),
    TXT(TXT),
    URI(URI),

    /// A record of a type we do not interpret; its bytes are kept verbatim.
    Other {
        type_number: UnknownQtype,
        bytes: Vec<u8>,
    },
}

/// A record type number that has no interpreting code, which may or may not
/// have a name that dog knows.
#[derive(PartialEq, Debug, Copy, Clone)]
pub enum UnknownQtype {
    /// A type number that dog has a name for, but cannot interpret.
    HeardOf(&'static str, u16),

    /// A type number dog knows nothing about.
    UnheardOf(u16),
}

impl UnknownQtype {
    pub fn number(self) -> u16 {
        match self {
            Self::HeardOf(_, n) => n,
            Self::UnheardOf(n) => n,
        }
    }
}

/// An IPv4 address.
#[derive(PartialEq, Debug)]
pub struct A {
    pub address: std::net::Ipv4Addr,
}

/// An IPv6 address.
#[derive(PartialEq, Debug)]
pub struct AAAA {
    pub address: std::net::Ipv6Addr,
}

/// A certificate authority authorisation.
#[derive(PartialEq, Debug)]
pub struct CAA {
    pub critical: bool,
    pub tag: String,
    pub value: String,
}

/// A canonical name.
#[derive(PartialEq, Debug)]
pub struct CNAME {
    pub domain: String,
}

/// A 48-bit MAC address.
#[derive(PartialEq, Debug)]
pub struct EUI48 {
    pub identifier: [u8; 6],
}

/// A 64-bit MAC address.
#[derive(PartialEq, Debug)]
pub struct EUI64 {
    pub identifier: [u8; 8],
}

/// Host information.
#[derive(PartialEq, Debug)]
pub struct HINFO {
    pub cpu: String,
    pub os: String,
}

/// A geographical location.
#[derive(PartialEq, Debug)]
pub struct LOC {
    pub version: u8,
    pub size: u8,
    pub horizontal_precision: u8,
    pub vertical_precision: u8,
    pub latitude: u32,
    pub longitude: u32,
    pub altitude: u32,
}

/// A mail exchange.
#[derive(PartialEq, Debug)]
pub struct MX {
    pub preference: u16,
    pub exchange: String,
}

/// A naming authority pointer.
#[derive(PartialEq, Debug)]
pub struct NAPTR {
    pub order: u16,
    pub preference: u16,
    pub flags: String,
    pub service: String,
    pub regex: String,
    pub replacement: String,
}

/// A nameserver.
#[derive(PartialEq, Debug)]
pub struct NS {
    pub nameserver: String,
}

/// An OpenPGP key.
#[derive(PartialEq, Debug)]
pub struct OPENPGPKEY {
    pub key: Vec<u8>,
}

/// A pointer to a canonical name.
#[derive(PartialEq, Debug)]
pub struct PTR {
    pub cname: String,
}

/// An SSH key fingerprint.
#[derive(PartialEq, Debug)]
pub struct SSHFP {
    pub algorithm: u8,
    pub fingerprint_type: u8,
    pub fingerprint: Vec<u8>,
}

/// Administrative information about a zone.
#[derive(PartialEq, Debug)]
pub struct SOA {
    pub mname: String,
    pub rname: String,
    pub serial: u32,
    pub refresh_interval: u32,
    pub retry_interval: u32,
    pub expire_limit: u32,
    pub minimum_ttl: u32,
}

/// A service record.
#[derive(PartialEq, Debug)]
pub struct SRV {
    pub priority: u16,
    pub weight: u16,
    pub port: u16,
    pub target: String,
}

/// A TLS certificate association.
#[derive(PartialEq, Debug)]
pub struct TLSA {
    pub certificate_usage: u8,
    pub selector: u8,
    pub matching_type: u8,
    pub certificate_data: Vec<u8>,
}

/// Arbitrary text.
#[derive(PartialEq, Debug)]
pub struct TXT {
    pub messages: Vec<String>,
}

/// A URI.
#[derive(PartialEq, Debug)]
pub struct URI {
    pub priority: u16,
    pub weight: u16,
    pub target: String,
}

/// The extension pseudo-record.
#[derive(PartialEq, Debug)]
pub struct OPT {
    pub udp_payload_size: u16,
    pub higher_bits: u8,
    pub edns0_version: u8,
    pub flags: u16,
    pub data: Vec<u8>,
}

// ---- parsing ----------------------------------------------------------

/// Reads a length-prefixed character string.
fn read_character_string(c: &mut Reader<'_>) -> Result<(String, u16), WireError> {
    let length = c.read_u8()?;
    let bytes = c.read_bytes(usize::from(length))?;
    let mut s = String::new();
    for b in &bytes {
        s.push(char::from(*b));
    }
    Ok((s, u16::from(length) + 1))
}

impl A {
    pub fn read(len: u16, c: &mut Reader<'_>) -> Result<Self, WireError> {
        if len != 4 {
            return Err(WireError::WrongRecordLength { stated_length: len, mandated_length: MandatedLength::Exactly(4) });
        }
        let mut buf = [0_u8; 4];
        for b in buf.iter_mut() {
            *b = c.read_u8()?;
        }
        Ok(A { address: std::net::Ipv4Addr::from(buf) })
    }
}

impl AAAA {
    pub fn read(len: u16, c: &mut Reader<'_>) -> Result<Self, WireError> {
        if len != 16 {
            return Err(WireError::WrongRecordLength { stated_length: len, mandated_length: MandatedLength::Exactly(16) });
        }
        let mut buf = [0_u8; 16];
        for b in buf.iter_mut() {
            *b = c.read_u8()?;
        }
        Ok(AAAA { address: std::net::Ipv6Addr::from(buf) })
    }
}

impl CAA {
    pub fn read(len: u16, c: &mut Reader<'_>) -> Result<Self, WireError> {
        let flags = c.read_u8()?;
        let tag_length = c.read_u8()?;
        let tag_bytes = c.read_bytes(usize::from(tag_length))?;
        let remaining = len.checked_sub(u16::from(tag_length) + 2).ok_or(WireError::IO)?;
        let value_bytes = c.read_bytes(usize::from(remaining))?;
        Ok(CAA {
            critical: flags & 0b1000_0000 == 0b1000_0000,
            tag: bytes_to_string(&tag_bytes),
            value: bytes_to_string(&value_bytes),
        })
    }
}

impl CNAME {
    pub fn read(_len: u16, c: &mut Reader<'_>) -> Result<Self, WireError> {
        let (domain, _) = c.read_labels()?;
        Ok(CNAME { domain })
    }
}

impl EUI48 {
    pub fn read(len: u16, c: &mut Reader<'_>) -> Result<Self, WireError> {
        if len != 6 {
            return Err(WireError::WrongRecordLength { stated_length: len, mandated_length: MandatedLength::Exactly(6) });
        }
        let mut identifier = [0_u8; 6];
        for b in identifier.iter_mut() {
            *b = c.read_u8()?;
        }
        Ok(EUI48 { identifier })
    }
}

impl EUI64 {
    pub fn read(len: u16, c: &mut Reader<'_>) -> Result<Self, WireError> {
        if len != 8 {
            return Err(WireError::WrongRecordLength { stated_length: len, mandated_length: MandatedLength::Exactly(8) });
        }
        let mut identifier = [0_u8; 8];
        for b in identifier.iter_mut() {
            *b = c.read_u8()?;
        }
        Ok(EUI64 { identifier })
    }
}

impl HINFO {
    pub fn read(len: u16, c: &mut Reader<'_>) -> Result<Self, WireError> {
        let (cpu, cpu_len) = read_character_string(c)?;
        let (os, os_len) = read_character_string(c)?;
        let length_after_labels = cpu_len + os_len;
        if len != length_after_labels {
            return Err(WireError::WrongLabelLength { stated_length: len, length_after_labels });
        }
        Ok(HINFO { cpu, os })
    }
}

impl LOC {
    pub fn read(len: u16, c: &mut Reader<'_>) -> Result<Self, WireError> {
        let version = c.read_u8()?;
        if version != 0 {
            return Err(WireError::WrongVersion { stated_version: version, maximum_supported_version: 0 });
        }
        if len != 16 {
            return Err(WireError::WrongRecordLength { stated_length: len, mandated_length: MandatedLength::Exactly(16) });
        }
        let size = c.read_u8()?;
        let horizontal_precision = c.read_u8()?;
        let vertical_precision = c.read_u8()?;
        let latitude = c.read_u32()?;
        let longitude = c.read_u32()?;
        let altitude = c.read_u32()?;
        Ok(LOC { version, size, horizontal_precision, vertical_precision, latitude, longitude, altitude })
    }
}

impl MX {
