// ---- parsing ----------------------------------------------------------

/// Reads a length-prefixed character string.
fn read_character_string(c: &mut Reader<'_>) -> Result<(String, u16), WireError> {
    let length = c.read_u8()?;
    let bytes = c.read_bytes(usize::from(length))?;
    let mut s = String::new();
    for b in &bytes {
        s.push(char::from(*b));
    }
    Ok((s, u16::from(length) + 1))
}

impl A {
    pub fn read(len: u16, c: &mut Reader<'_>) -> Result<Self, WireError> {
        if len != 4 {
            return Err(WireError::WrongRecordLength { stated_length: len, mandated_length: MandatedLength::Exactly(4) });
        }
        let mut buf = [0_u8; 4];
        for b in buf.iter_mut() {
            *b = c.read_u8()?;
        }
        Ok(A { address: std::net::Ipv4Addr::from(buf) })
    }
}

impl AAAA {
    pub fn read(len: u16, c: &mut Reader<'_>) -> Result<Self, WireError> {
        if len != 16 {
            return Err(WireError::WrongRecordLength { stated_length: len, mandated_length: MandatedLength::Exactly(16) });
        }
        let mut buf = [0_u8; 16];
        for b in buf.iter_mut() {
            *b = c.read_u8()?;
        }
        Ok(AAAA { address: std::net::Ipv6Addr::from(buf) })
    }
}

impl CAA {
    pub fn read(len: u16, c: &mut Reader<'_>) -> Result<Self, WireError> {
        let flags = c.read_u8()?;
        let tag_length = c.read_u8()?;
        let tag_bytes = c.read_bytes(usize::from(tag_length))?;
        let remaining = len.checked_sub(u16::from(tag_length) + 2).ok_or(WireError::IO)?;
        let value_bytes = c.read_bytes(usize::from(remaining))?;
        Ok(CAA {
            critical: flags & 0b1000_0000 == 0b1000_0000,
            tag: bytes_to_string(&tag_bytes),
            value: bytes_to_string(&value_bytes),
        })
    }
}

