    pub fn read(len: u16, c: &mut Reader<'_>) -> Result<Self, WireError> {
        if len != 6 {
            return Err(WireError::WrongRecordLength { stated_length: len, mandated_length: MandatedLength::Exactly(6) });
        }
        let mut identifier = [0_u8; 6];
        for b in identifier.iter_mut() {
            *b = c.read_u8()?;
        }
        Ok(EUI48 { identifier })
    }
}

impl EUI64 {
    pub fn read(len: u16, c: &mut Reader<'_>) -> Result<Self, WireError> {
        if len != 8 {
