//! DNS packets: the header, the question, and the resource records.

pub mod record;
pub mod wire;

use self::record::*;
use self::wire::*;

/// The network class of a DNS record.
#[derive(PartialEq, Debug, Copy, Clone)]
pub enum QClass {
    /// The Internet class.
    IN,

    /// The Chaosnet class.
    CH,

    /// The Hesiod class.
    HS,

    /// Some other class, by number.
    Other(u16),
}

impl QClass {
    pub fn from_number(num: u16) -> Self {
        match num {
            0x0001 => Self::IN,
            0x0003 => Self::CH,
            0x0004 => Self::HS,
            _ => Self::Other(num),
        }
    }

    pub fn to_number(self) -> u16 {
        match self {
            Self::IN => 0x0001,
            Self::CH => 0x0003,
            Self::HS => 0x0004,
            Self::Other(num) => num,
        }
    }

    /// Parses a class from a command-line argument.
    pub fn from_str(input: &str) -> Option<Self> {
        match &*input.to_ascii_uppercase() {
            "IN" => Some(Self::IN),
            "CH" => Some(Self::CH),
            "HS" => Some(Self::HS),
            _ => input.parse::<u16>().ok().map(Self::from_number),
        }
    }
}

/// A question in the question section of a DNS packet.
#[derive(PartialEq, Debug, Clone)]
pub struct Query {
    pub qname: String,
    pub qclass: QClass,
    pub qtype: u16,
}

impl Query {
    fn read(c: &mut Reader<'_>) -> Result<Self, WireError> {
        let (qname, _) = c.read_labels()?;
        let qtype = c.read_u16()?;
        let qclass = QClass::from_number(c.read_u16()?);
        Ok(Query { qname, qclass, qtype })
    }

    fn write(&self, w: &mut Writer) {
        w.name(&self.qname);
        w.u16(self.qtype);
        w.u16(self.qclass.to_number());
    }
}

/// An entry in one of the three record sections of a DNS packet.
#[derive(PartialEq, Debug)]
pub enum Answer {
    /// An ordinary resource record.
    Standard {
        qname: String,
        qclass: QClass,
        ttl: u32,
        record: Record,
    },

    /// The EDNS pseudo-record, which re-uses the class and TTL fields for
    /// other purposes.
    Pseudo { qname: String, opt: OPT },
}

/// The flags in the second and third bytes of a DNS packet.
#[derive(PartialEq, Debug, Copy, Clone, Default)]
pub struct Flags {
    pub response: bool,
    pub opcode: u8,
    pub authoritative: bool,
    pub truncated: bool,
    pub recursion_desired: bool,
    pub recursion_available: bool,
    pub authentic_data: bool,
    pub checking_disabled: bool,
    pub error_code: u8,
}

impl Flags {
    /// The flags dog sets on an outgoing query.
    pub fn query() -> Self {
        Flags { recursion_desired: true, ..Flags::default() }
    }

    pub fn from_u16(bits: u16) -> Self {
        Flags {
            response: bits >> 15 == 1,
            opcode: ((bits >> 11) & 0b1111) as u8,
            authoritative: (bits >> 10) & 1 == 1,
            truncated: (bits >> 9) & 1 == 1,
            recursion_desired: (bits >> 8) & 1 == 1,
            recursion_available: (bits >> 7) & 1 == 1,
            authentic_data: (bits >> 5) & 1 == 1,
            checking_disabled: (bits >> 4) & 1 == 1,
            error_code: (bits & 0b1111) as u8,
        }
    }

    pub fn to_u16(self) -> u16 {
        let mut bits = 0_u16;
        if self.response {
            bits |= 1 << 15;
        }
        bits |= u16::from(self.opcode & 0b1111) << 11;
        if self.authoritative {
            bits |= 1 << 10;
        }
        if self.truncated {
            bits |= 1 << 9;
        }
        if self.recursion_desired {
            bits |= 1 << 8;
        }
        if self.recursion_available {
            bits |= 1 << 7;
        }
        if self.authentic_data {
            bits |= 1 << 5;
        }
        if self.checking_disabled {
            bits |= 1 << 4;
        }
        bits |= u16::from(self.error_code & 0b1111);
        bits
    }
}

/// An outgoing DNS query packet.
#[derive(PartialEq, Debug)]
pub struct Request {
    pub transaction_id: u16,
    pub flags: Flags,
    pub query: Query,
    pub additional: Option<OPT>,
}

impl Request {
    pub fn to_bytes(&self) -> Vec<u8> {
        let mut w = Writer::new();
        w.u16(self.transaction_id);
        w.u16(self.flags.to_u16());
        w.u16(1); // qdcount
        w.u16(0); // ancount
        w.u16(0); // nscount
        w.u16(if self.additional.is_some() { 1 } else { 0 });
        self.query.write(&mut w);
        if let Some(opt) = &self.additional {
            w.raw(&opt.to_bytes());
        }
        w.bytes
    }
}

/// An incoming DNS response packet.
#[derive(PartialEq, Debug)]
pub struct Response {
    pub transaction_id: u16,
    pub flags: Flags,
    pub queries: Vec<Query>,
    pub answers: Vec<Answer>,
    pub authorities: Vec<Answer>,
    pub additionals: Vec<Answer>,
}

impl Response {
    pub fn from_bytes(bytes: &[u8]) -> Result<Self, WireError> {
        let mut c = Reader::new(bytes);

        let transaction_id = c.read_u16()?;
        let flags = Flags::from_u16(c.read_u16()?);
        let query_count = c.read_u16()?;
        let answer_count = c.read_u16()?;
        let authority_count = c.read_u16()?;
        let additional_count = c.read_u16()?;

        let mut queries = Vec::with_capacity(usize::from(query_count));
        for _ in 0..query_count {
            queries.push(Query::read(&mut c)?);
        }

        let mut answers = Vec::with_capacity(usize::from(answer_count));
        for _ in 0..answer_count {
            answers.push(read_answer(&mut c)?);
        }

        let mut authorities = Vec::with_capacity(usize::from(authority_count));
        for _ in 0..authority_count {
            authorities.push(read_answer(&mut c)?);
        }

        let mut additionals = Vec::with_capacity(usize::from(additional_count));
        for _ in 0..additional_count {
            additionals.push(read_answer(&mut c)?);
        }

        Ok(Response { transaction_id, flags, queries, answers, authorities, additionals })
    }
}

fn read_answer(c: &mut Reader<'_>) -> Result<Answer, WireError> {
    let (qname, _) = c.read_labels()?;
    let qtype = c.read_u16()?;

    if qtype == 41 {
        let opt = OPT::read(c)?;
        return Ok(Answer::Pseudo { qname, opt });
    }

    let qclass = QClass::from_number(c.read_u16()?);
    let ttl = c.read_u32()?;
    let len = c.read_u16()?;
    let record = read_record(qtype, len, c)?;
    Ok(Answer::Standard { qname, qclass, ttl, record })
}

/// Every record type number dog has a name for, in ascending order.
pub static TYPE_NAMES: &[(u16, &str)] = &[
    (1, "A"),
    (2, "NS"),
    (5, "CNAME"),
    (6, "SOA"),
    (12, "PTR"),
    (13, "HINFO"),
    (15, "MX"),
    (16, "TXT"),
    (17, "RP"),
    (18, "AFSDB"),
    (24, "SIG"),
    (25, "KEY"),
    (28, "AAAA"),
    (29, "LOC"),
    (33, "SRV"),
    (35, "NAPTR"),
    (36, "KX"),
    (37, "CERT"),
    (39, "DNAME"),
    (42, "APL"),
    (43, "DS"),
    (44, "SSHFP"),
    (45, "IPSECKEY"),
    (46, "RRSIG"),
    (47, "NSEC"),
    (48, "DNSKEEYE"),
    (49, "DHCID"),
    (50, "NSEC3"),
    (51, "NSEC3PARAM"),
    (52, "TLSA"),
    (53, "SMIMEA"),
    (55, "HIP"),
    (59, "CDS"),
    (60, "CDNSKEY"),
    (61, "OPENPGPKEY"),
    (62, "CSYNC"),
    (108, "EUI48"),
    (109, "EUI64"),
    (249, "TKEY"),
    (250, "TSIG"),
    (251, "IXFR"),
    (252, "AXFR"),
    (255, "ANY"),
    (256, "URI"),
    (257, "CAA"),
    (32768, "TA"),
    (32769, "DLV"),
];

/// Looks up the name dog uses for a record type number.
pub fn type_name(number: u16) -> Option<&'static str> {
    TYPE_NAMES.iter().find(|(n, _)| *n == number).map(|(_, s)| *s)
}

/// Parses a record type from a command-line argument.
pub fn type_from_str(input: &str) -> Option<u16> {
    let upper = input.to_ascii_uppercase();
    for (number, name) in TYPE_NAMES {
        if *name == upper {
            return Some(*number);
        }
    }
    input.parse::<u16>().ok()
}

fn read_record(qtype: u16, len: u16, c: &mut Reader<'_>) -> Result<Record, WireError> {
    match qtype {
        1 => Ok(Record::A(A::read(len, c)?)),
        2 => Ok(Record::NS(NS::read(len, c)?)),
        5 => Ok(Record::CNAME(CNAME::read(len, c)?)),
        6 => Ok(Record::SOA(SOA::read(len, c)?)),
        12 => Ok(Record::PTR(PTR::read(len, c)?)),
        13 => Ok(Record::HINFO(HINFO::read(len, c)?)),
        15 => Ok(Record::MX(MX::read(len, c)?)),
        16 => Ok(Record::TXT(TXT::read(len, c)?)),
        28 => Ok(Record::AAAA(AAAA::read(len, c)?)),
        29 => Ok(Record::LOC(LOC::read(len, c)?)),
        33 => Ok(Record::SRV(SRV::read(len, c)?)),
        35 => Ok(Record::NAPTR(NAPTR::read(len, c)?)),
        44 => Ok(Record::SSHFP(SSHFP::read(len, c)?)),
        52 => Ok(Record::TLSA(TLSA::read(len, c)?)),
        61 => Ok(Record::OPENPGPKEY(OPENPGPKEY::read(len, c)?)),
        108 => Ok(Record::EUI48(EUI48::read(len, c)?)),
        109 => Ok(Record::EUI64(EUI64::read(len, c)?)),
        256 => Ok(Record::URI(URI::read(len, c)?)),
        257 => Ok(Record::CAA(CAA::read(len, c)?)),
        _ => {
            let bytes = c.read_bytes(usize::from(len))?;
            let type_number = match type_name(qtype) {
                Some(name) => UnknownQtype::HeardOf(name, qtype),
                None => UnknownQtype::UnheardOf(qtype),
            };
            Ok(Record::Other { type_number, bytes })
        }
    }
}

