//! Turning DNS responses into text for the user.

use crate::colours;
use crate::colours::Style;
use crate::dns::record::*;
use crate::dns::*;

/// Whether durations get formatted or printed as a plain number of seconds.
#[derive(PartialEq, Debug, Copy, Clone)]
pub enum TextFormat {
    Formatted,
    Seconds,
}

impl TextFormat {
    pub fn format_duration(self, seconds: u32) -> String {
        match self {
            Self::Seconds => seconds.to_string(),
            Self::Formatted => format_duration(seconds),
        }
    }
}

/// Turns a number of seconds into a human-readable duration.
pub fn format_duration(seconds: u32) -> String {
    let (mins, secs) = (seconds / 60, seconds % 60);
    let (hours, mins) = (mins / 60, mins % 60);
    let (days, hours) = (hours / 24, hours % 24);

    if days > 0 {
        format!("{}d{}h{:02}m{:02}s", days, hours, mins, secs)
    } else if hours > 0 {
        format!("{}h{:02}m{:02}s", hours, mins, secs)
    } else if mins > 0 {
        format!("{}m{:02}s", mins, secs)
    } else {
        format!("{}s", secs)
    }
}

/// Escapes a byte-per-char string for display in the table.
pub fn escape(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for c in input.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            _ if c >= ' ' && c <= '\u{7f}' => out.push(c),
            _ => {
                out.push('\\');
                out.push_str(&(c as u32).to_string());
            }
        }
    }
    out
}

/// Escapes a byte-per-char string and wraps it in double quotes.
pub fn quoted(input: &str) -> String {
    format!("\"{}\"", escape(input))
}

/// Re-reads a byte-per-char string as UTF-8, replacing bad sequences.
pub fn lossy(input: &str) -> String {
    let bytes: Vec<u8> = input.chars().map(|c| c as u8).collect();
    String::from_utf8_lossy(&bytes).into_owned()
}

/// Formats a run of bytes the way `Vec<u8>`’s debug output does.
pub fn byte_list(bytes: &[u8]) -> String {
    let mut out = String::from("[");
    for (i, b) in bytes.iter().enumerate() {
        if i > 0 {
            out.push_str(", ");
        }
        out.push_str(&b.to_string());
    }
    out.push(']');
    out
}

/// Formats a run of bytes as lowercase hexadecimal.
pub fn hex_string(bytes: &[u8]) -> String {
    let mut out = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        out.push_str(&format!("{:02x}", b));
    }
    out
}

/// Formats a run of bytes as standard base64 with padding.
pub fn base64_encode(bytes: &[u8]) -> String {
    const ALPHABET: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::new();
    for chunk in bytes.chunks(3) {
        let b0 = u32::from(chunk[0]);
        let b1 = chunk.get(1).map_or(0, |b| u32::from(*b));
        let b2 = chunk.get(2).map_or(0, |b| u32::from(*b));
        let n = (b0 << 16) | (b1 << 8) | b2;
        out.push(char::from(ALPHABET[((n >> 18) & 0x3f) as usize]));
        out.push(char::from(ALPHABET[((n >> 12) & 0x3f) as usize]));
        if chunk.len() > 1 {
            out.push(char::from(ALPHABET[((n >> 6) & 0x3f) as usize]));
        } else {
            out.push('=');
        }
        if chunk.len() > 2 {
            out.push(char::from(ALPHABET[(n & 0x3f) as usize]));
        } else {
            out.push('=');
        }
    }
    out
}

/// Formats a MAC-address-style identifier.
fn identifier(bytes: &[u8]) -> String {
    let mut out = String::new();
    for (i, b) in bytes.iter().enumerate() {
        if i > 0 {
            out.push('-');
        }
        out.push_str(&format!("{:02x}", b));
    }
    out
}

impl Record {
    /// The name dog shows in the type column.
    pub fn type_name(&self) -> String {
        match self {
            Self::A(_) => "A".into(),
            Self::AAAA(_) => "AAAA".into(),
            Self::CAA(_) => "CAA".into(),
            Self::CNAME(_) => "CNAME".into(),
            Self::EUI48(_) => "EUI48".into(),
            Self::EUI64(_) => "EUI64".into(),
            Self::HINFO(_) => "HINFO".into(),
            Self::LOC(_) => "LOC".into(),
            Self::MX(_) => "MX".into(),
            Self::NAPTR(_) => "NAPTR".into(),
            Self::NS(_) => "NS".into(),
            Self::OPENPGPKEY(_) => "OPENPGPKEY".into(),
            Self::PTR(_) => "PTR".into(),
            Self::SSHFP(_) => "SSHFP".into(),
            Self::SOA(_) => "SOA".into(),
            Self::SRV(_) => "SRV".into(),
            Self::TLSA(_) => "TLSA".into(),
            Self::TXT(_) => "TXT".into(),
            Self::URI(_) => "URI".into(),
            Self::Other { type_number, .. } => match type_number {
                UnknownQtype::HeardOf(name, _) => (*name).into(),
                UnknownQtype::UnheardOf(num) => num.to_string(),
            },
        }
    }

    /// The style the type column gets painted in.
    pub fn style(&self) -> Style {
        match self {
            Self::A(_) => colours::TYPE_A,
            Self::AAAA(_) => colours::TYPE_AAAA,
            Self::CAA(_) => colours::TYPE_CAA,
            Self::CNAME(_) => colours::TYPE_CNAME,
            Self::EUI48(_) => colours::TYPE_EUI48,
            Self::EUI64(_) => colours::TYPE_EUI64,
            Self::HINFO(_) => colours::TYPE_HINFO,
            Self::LOC(_) => colours::TYPE_LOC,
            Self::MX(_) => colours::TYPE_MX,
            Self::NAPTR(_) => colours::TYPE_NAPTR,
            Self::NS(_) => colours::TYPE_NS,
            Self::OPENPGPKEY(_) => colours::TYPE_OPENPGPKEY,
            Self::PTR(_) => colours::TYPE_PTR,
            Self::SSHFP(_) => colours::TYPE_SSHFP,
            Self::SOA(_) => colours::TYPE_SOA,
            Self::SRV(_) => colours::TYPE_SRV,
            Self::TLSA(_) => colours::TYPE_TLSA,
            Self::TXT(_) => colours::TYPE_TXT,
            Self::URI(_) => colours::TYPE_URI,
            Self::Other { .. } => colours::TYPE_UNKNOWN,
        }
    }

    /// The contents of the data column.
    pub fn summary(&self, tf: TextFormat) -> String {
        match self {
            Self::A(rec) => rec.address.to_string(),
            Self::AAAA(rec) => rec.address.to_string(),
            Self::CAA(rec) => format!(
                "{} {} ({})",
                quoted(&rec.tag),
                quoted(&rec.value),
                if rec.critical { "critical" } else { "non-critical" }
            ),
            Self::CNAME(rec) => quoted(&rec.domain),
            Self::EUI48(rec) => quoted(&identifier(&rec.identifier)),
            Self::EUI64(rec) => quoted(&identifier(&rec.identifier)),
            Self::HINFO(rec) => format!("{} {}", quoted(&rec.cpu), quoted(&rec.os)),
            Self::LOC(rec) => rec.summary(),
            Self::MX(rec) => format!("{} {}", rec.preference, quoted(&rec.exchange)),
            Self::NAPTR(rec) => format!(
                "{} {} {} {} {} {}",
                rec.order,
                rec.preference,
                quoted(&rec.flags),
                quoted(&rec.service),
                quoted(&rec.regex),
                quoted(&rec.replacement)
            ),
            Self::NS(rec) => quoted(&rec.nameserver),
            Self::OPENPGPKEY(rec) => quoted(&base64_encode(&rec.key)),
            Self::PTR(rec) => quoted(&rec.cname),
            Self::SSHFP(rec) => format!(
                "{} {} {}",
                rec.algorithm,
                rec.fingerprint_type,
                hex_string(&rec.fingerprint)
            ),
            Self::SOA(rec) => format!(
                "{} {} {} {} {} {} {}",
                quoted(&rec.mname),
                quoted(&rec.rname),
                rec.serial,
                tf.format_duration(rec.refresh_interval),
                tf.format_duration(rec.retry_interval),
                tf.format_duration(rec.expire_limit),
                tf.format_duration(rec.minimum_ttl)
            ),
            Self::SRV(rec) => format!(
                "{} {} {}:{}",
                rec.priority,
                rec.weight,
                quoted(&rec.target),
                rec.port
            ),
            Self::TLSA(rec) => format!(
                "{} {} {} {}",
                rec.certificate_usage,
                rec.selector,
                rec.matching_type,
                quoted(&hex_string(&rec.certificate_data))
            ),
            Self::TXT(rec) => {
                let strings: Vec<String> = rec.messages.iter().map(|m| quoted(m)).collect();
                strings.join(", ")
            }
            Self::URI(rec) => format!("{} {} {}", rec.priority, rec.weight, quoted(&rec.target)),
            Self::Other { bytes, .. } => byte_list(bytes),
        }
    }
}

impl OPT {
    pub fn summary(&self) -> String {
        format!(
            "{} {} {} {} {}",
            self.udp_payload_size,
            self.higher_bits,
            self.edns0_version,
            self.flags,
            byte_list(&self.data)
        )
    }
}

