use crate::output::render::*;

/// Which of the three record sections a row came from.
#[derive(PartialEq, Debug, Copy, Clone)]
pub enum Section {
    Answer,
    Authority,
    Additional,
}

impl Section {
    fn mark(self) -> &'static str {
        match self {
            Self::Answer => " ",
            Self::Authority => "A",
            Self::Additional => "+",
        }
    }

    fn style(self) -> colours::Style {
        match self {
            Self::Answer => colours::ANSWER_MARK,
            Self::Authority => colours::AUTHORITY_MARK,
            Self::Additional => colours::ADDITIONAL_MARK,
        }
    }
}

/// How the user wants the results printed.
#[derive(PartialEq, Debug, Copy, Clone)]
pub enum OutputFormat {
    /// A table of results.
    Text(bool, TextFormat),

    /// Nothing but the record summaries.
    Short(TextFormat),

    /// A JSON object.
    JSON,
}

impl OutputFormat {
    /// Prints the given responses. Returns whether anything was printed,
    /// which short mode uses to decide its exit code.
    pub fn print(self, responses: Vec<Response>, duration: Option<Duration>) -> bool {
        match self {
            Self::Short(tf) => {
                let mut printed = false;
                for response in responses {
                    for answer in response.answers {
                        if let Answer::Standard { record, .. } = answer {
                            println!("{}", record.summary(tf));
                            printed = true;
                        }
                    }
                }
                printed
            }

            Self::JSON => {
                println!("{}", json::render(&responses, duration));
                true
            }

            Self::Text(colours, tf) => {
                let mut table = Table::new(colours, tf);

                for response in responses {
                    if response.flags.error_code != 0 {
                        println!("Status: {}", error_code_name(response.flags.error_code));
                    }

                    for a in response.answers {
                        table.add_row(a, Section::Answer);
                    }
                    for a in response.authorities {
                        table.add_row(a, Section::Authority);
                    }
                    for a in response.additionals {
                        table.add_row(a, Section::Additional);
                    }
                }

                table.print();

                if let Some(duration) = duration {
                    println!("Ran in {}ms", duration.as_millis());
                }

                true
            }
        }
    }
}

/// The name dog gives to a response code.
pub fn error_code_name(code: u8) -> String {
    match code {
        1 => "Format Error".into(),
        2 => "Server Failure".into(),
        3 => "NXDomain".into(),
        4 => "Not Implemented".into(),
        5 => "Query Refused".into(),
        n => format!("Other Failure ({})", n),
    }
}

/// One line of the results table.
struct Row {
    qtype: String,
    qname: String,
    ttl: String,
    section: Section,
    summary: String,
    style: colours::Style,
}

/// The results table, which needs every row before it can be printed so that
/// the columns can be aligned.
struct Table {
    rows: Vec<Row>,
    colours: bool,
    tf: TextFormat,
}

impl Table {
    fn new(colours: bool, tf: TextFormat) -> Self {
        Table { rows: Vec::new(), colours, tf }
    }

    fn add_row(&mut self, answer: Answer, section: Section) {
        match answer {
            Answer::Standard { qname, ttl, record, .. } => {
                self.rows.push(Row {
                    qtype: record.type_name(),
                    qname,
                    ttl: self.tf.format_duration(ttl),
                    section,
                    summary: record.summary(self.tf),
                    style: record.style(),
                });
            }
            Answer::Pseudo { qname, opt } => {
                self.rows.push(Row {
                    qtype: "OPT".into(),
                    qname,
                    ttl: String::new(),
                    section,
                    summary: opt.summary(),
                    style: colours::TYPE_OPT,
                });
            }
        }
    }

    fn print(&self) {
        let qtype_width = self.rows.iter().map(|r| r.qtype.chars().count()).max().unwrap_or(0);
        let qname_width = self.rows.iter().map(|r| r.qname.chars().count()).max().unwrap_or(0);
        let ttl_width = self.rows.iter().map(|r| r.ttl.chars().count()).max().unwrap_or(0);

        for row in &self.rows {
            let mut line = String::new();

            for _ in 0..qtype_width - row.qtype.chars().count() {
                line.push(' ');
            }
            line.push_str(&colours::paint(self.colours, row.style, &row.qtype));
            line.push(' ');

            line.push_str(&colours::paint(self.colours, colours::QNAME, &row.qname));
            for _ in 0..qname_width - row.qname.chars().count() {
                line.push(' ');
            }
            line.push(' ');

            for _ in 0..ttl_width - row.ttl.chars().count() {
                line.push(' ');
            }
            line.push_str(&row.ttl);
            line.push(' ');

            if row.section == Section::Answer {
                line.push(' ');
            } else {
                line.push_str(&colours::paint(self.colours, row.section.style(), row.section.mark()));
            }
            line.push(' ');

            line.push_str(&row.summary);
            println!("{}", line);
        }
    }
}

