//! Rendering responses as JSON.

use std::time::Duration;

use crate::dns::record::*;
use crate::dns::*;
use crate::output::render::*;

/// A tiny JSON writer: dog’s output has a fixed shape, so all this needs to
/// do is keep track of commas and escape strings properly.
pub struct Json {
    out: String,
    fresh: bool,
}

impl Json {
    pub fn new() -> Self {
        Json { out: String::new(), fresh: true }
    }

    fn comma(&mut self) {
        if self.fresh {
            self.fresh = false;
        } else {
            self.out.push(',');
        }
    }

    pub fn object(&mut self) {
        self.comma();
        self.out.push('{');
        self.fresh = true;
    }

    pub fn end_object(&mut self) {
        self.out.push('}');
        self.fresh = false;
    }

    pub fn array(&mut self) {
        self.comma();
        self.out.push('[');
        self.fresh = true;
    }

    pub fn end_array(&mut self) {
        self.out.push(']');
        self.fresh = false;
    }

    pub fn key(&mut self, name: &str) {
        self.comma();
        write_json_string(&mut self.out, name);
        self.out.push(':');
        self.fresh = true;
    }

    pub fn string(&mut self, value: &str) {
        self.comma();
        write_json_string(&mut self.out, value);
        self.fresh = false;
    }

    pub fn number(&mut self, value: u64) {
        self.comma();
        self.out.push_str(&value.to_string());
        self.fresh = false;
    }

    pub fn boolean(&mut self, value: bool) {
        self.comma();
        self.out.push_str(if value { "true" } else { "false" });
        self.fresh = false;
    }

    pub fn finish(self) -> String {
        self.out
    }
}

/// Escapes a string the way serde_json does.
fn write_json_string(out: &mut String, value: &str) {
    out.push('"');
    for c in value.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{8}' => out.push_str("\\b"),
            '\u{9}' => out.push_str("\\t"),
            '\u{a}' => out.push_str("\\n"),
            '\u{c}' => out.push_str("\\f"),
            '\u{d}' => out.push_str("\\r"),
            _ if (c as u32) < 0x20 => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            _ => out.push(c),
        }
    }
    out.push('"');
}

fn write_class(j: &mut Json, qclass: QClass) {
    match qclass {
        QClass::IN => j.string("IN"),
        QClass::CH => j.string("CH"),
        QClass::HS => j.string("HS"),
        QClass::Other(num) => j.number(u64::from(num)),
    }
}

fn write_type_number(j: &mut Json, number: u16) {
    match type_name(number) {
        Some(name) => j.string(name),
        None => j.number(u64::from(number)),
    }
}

fn write_bytes(j: &mut Json, bytes: &[u8]) {
    j.array();
    for b in bytes {
        j.number(u64::from(*b));
    }
    j.end_array();
}

fn write_answer(j: &mut Json, answer: &Answer) {
    match answer {
        Answer::Standard { qname, qclass, ttl, record } => {
            j.object();
            j.key("name");
            j.string(&lossy(qname));
            j.key("class");
            write_class(j, *qclass);
            j.key("ttl");
            j.number(u64::from(*ttl));
            j.key("type");
            match record {
                Record::Other { type_number, .. } => match type_number {
                    UnknownQtype::HeardOf(name, _) => j.string(name),
                    UnknownQtype::UnheardOf(num) => j.number(u64::from(*num)),
                },
                _ => j.string(&record.type_name()),
            }
            j.key("data");
            write_record_data(j, record);
            j.end_object();
        }
        Answer::Pseudo { qname, opt } => {
            j.object();
            j.key("name");
            j.string(&lossy(qname));
            j.key("type");
            j.string("OPT");
            j.key("data");
            j.object();
            j.key("version");
            j.number(u64::from(opt.edns0_version));
            j.key("data");
            write_bytes(j, &opt.data);
            j.end_object();
            j.end_object();
        }
    }
}

fn write_record_data(j: &mut Json, record: &Record) {
    j.object();
    match record {
        Record::A(rec) => {
            j.key("address");
            j.string(&rec.address.to_string());
        }
        Record::AAAA(rec) => {
            j.key("address");
            j.string(&rec.address.to_string());
        }
        Record::CAA(rec) => {
            j.key("critical");
            j.boolean(rec.critical);
            j.key("tag");
            j.string(&lossy(&rec.tag));
            j.key("value");
            j.string(&lossy(&rec.value));
        }
        Record::CNAME(rec) => {
            j.key("domain");
            j.string(&rec.domain);
        }
        Record::EUI48(rec) => {
            j.key("identifier");
            j.string(&mac_address(&rec.identifier));
        }
        Record::EUI64(rec) => {
            j.key("identifier");
            j.string(&mac_address(&rec.identifier));
        }
        Record::HINFO(rec) => {
            j.key("cpu");
            j.string(&lossy(&rec.cpu));
            j.key("os");
            j.string(&lossy(&rec.os));
        }
        Record::LOC(rec) => {
            j.key("size");
            j.string(&rec.size_string());
            j.key("precision");
            j.object();
            j.key("horizontal");
            j.number(u64::from(rec.horizontal_precision));
            j.key("vertical");
            j.number(u64::from(rec.vertical_precision));
            j.end_object();
            j.key("point");
            j.object();
            j.key("latitude");
            j.string(&rec.latitude_string());
            j.key("longitude");
            j.string(&rec.longitude_string());
            j.key("altitude");
            j.string(&rec.altitude_string());
            j.end_object();
        }
        Record::MX(rec) => {
            j.key("preference");
            j.number(u64::from(rec.preference));
            j.key("exchange");
            j.string(&rec.exchange);
        }
        Record::NAPTR(rec) => {
            j.key("order");
            j.number(u64::from(rec.order));
            j.key("flags");
            j.string(&lossy(&rec.flags));
            j.key("service");
            j.string(&lossy(&rec.service));
            j.key("regex");
            j.string(&lossy(&rec.regex));
            j.key("replacement");
            j.string(&rec.replacement);
        }
        Record::NS(rec) => {
            j.key("nameserver");
            j.string(&rec.nameserver);
        }
        Record::OPENPGPKEY(rec) => {
            j.key("key");
            j.string(&base64_encode(&rec.key));
        }
        Record::PTR(rec) => {
            j.key("cname");
            j.string(&rec.cname);
        }
        Record::SSHFP(rec) => {
            j.key("algorithm");
            j.number(u64::from(rec.algorithm));
            j.key("fingerprint_type");
            j.number(u64::from(rec.fingerprint_type));
            j.key("fingerprint");
            j.string(&hex_string(&rec.fingerprint));
        }
        Record::SOA(rec) => {
            j.key("mname");
            j.string(&rec.mname);
        }
        Record::SRV(rec) => {
            j.key("priority");
            j.number(u64::from(rec.priority));
            j.key("weight");
            j.number(u64::from(rec.weight));
            j.key("port");
            j.number(u64::from(rec.port));
            j.key("target");
            j.string(&rec.target);
        }
        Record::TLSA(rec) => {
            j.key("certificate_usage");
            j.number(u64::from(rec.certificate_usage));
            j.key("selector");
            j.number(u64::from(rec.selector));
            j.key("matching_type");
            j.number(u64::from(rec.matching_type));
            j.key("certificate_data");
            j.string(&hex_string(&rec.certificate_data));
        }
        Record::TXT(rec) => {
            j.key("messages");
            j.array();
            for message in &rec.messages {
                j.string(&lossy(message));
            }
            j.end_array();
        }
        Record::URI(rec) => {
            j.key("priority");
            j.number(u64::from(rec.priority));
            j.key("weight");
            j.number(u64::from(rec.weight));
            j.key("target");
            j.string(&lossy(&rec.target));
        }
        Record::Other { bytes, .. } => {
            j.key("bytes");
            write_bytes(j, bytes);
        }
    }
    j.end_object();
}

/// Renders a set of responses as one JSON object.
pub fn render(responses: &[Response], duration: Option<Duration>) -> String {
    let mut j = Json::new();
    j.object();
    j.key("responses");
    j.array();

    for response in responses {
        j.object();

        j.key("queries");
        j.array();
        for query in &response.queries {
            j.object();
            j.key("name");
            j.string(&lossy(&query.qname));
            j.key("class");
            write_class(&mut j, query.qclass);
            j.key("type");
            write_type_number(&mut j, query.qtype);
            j.end_object();
        }
        j.end_array();

        for (key, answers) in [
            ("answers", &response.answers),
            ("authorities", &response.authorities),
            ("additionals", &response.additionals),
        ] {
            j.key(key);
            j.array();
            for answer in answers.iter() {
                write_answer(&mut j, answer);
            }
            j.end_array();
        }

        j.end_object();
    }

    j.end_array();

    if let Some(duration) = duration {
        j.key("duration");
        j.object();
        j.key("secs");
        j.number(duration.as_secs());
        j.key("millis");
        j.number(u64::from(duration.subsec_millis()));
        j.end_object();
    }

    j.end_object();
    j.finish()
}

